#photo-layer{position:absolute;inset:0;pointer-events:none;overflow:hidden;transition:opacity .35s}.memory-card{position:absolute;left:0;top:0;padding:2px;border:1px solid #b9ab82;background:#151719;border-radius:1px;box-shadow:0 2px 9px #0008;pointer-events:auto;will-change:transform;transition:box-shadow .12s;touch-action:manipulation;transform-origin:center}.memory-card img{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none}.memory-card.photo-hover{box-shadow:0 0 0 1px #fff0bd,0 0 18px #e9c77355}.photo-open #sky,.photo-open #photo-layer{opacity:.17}
