@media(max-width:700px){#photo-entry{padding:26px 26px 24px}.entry-header{font-size:13px}.entry-edition{font-size:11px}.entry-content{left:9vw;top:17%;transform:none;width:85vw}.entry-content h1{font-size:clamp(62px,15vw,96px);margin-bottom:22px}.entry-description{font-size:14px;margin-bottom:26px}.entry-actions{gap:26px}.entry-primary{height:46px;min-width:156px;padding:0 18px;gap:36px}#photo-import-status{font-size:11px;margin-top:17px}.entry-footer{justify-content:space-between;gap:14px;font-size:11px;padding-top:16px}.entry-key{display:block;margin:6px 0 0;color:#53616a}#focus-photo{max-width:92vw;max-height:68vh;border-width:3px}#photo-toolbar{right:20px;top:18px}.focus-hint{font-size:11px}}
@media(max-height:560px) and (min-width:701px){.entry-content h1{font-size:75px;margin-bottom:18px}.entry-description{margin-bottom:20px}.entry-content{top:49%}#photo-import-status{margin-top:12px}}
#tree-entrance{display:none}.tree-waiting #photo-layer,.tree-waiting #photo-toolbar,.tree-entering #photo-toolbar{opacity:0;pointer-events:none}.tree-entering #photo-layer,.tree-entering #photo-layer button,.tree-entering #sky,.tree-waiting #sky{pointer-events:none}@media(prefers-reduced-motion:reduce){.memory-card,#photo-layer,#sky,#photo-entry{transition:none}#focus-photo{animation:none}}
